From 237289828e15924a9f0e3fd2dfffb496df880987 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 16:48:57 +0100
Subject: [PATCH] desktoppackage/configuration: Don't open settings on a hidden
 page

A widget whose first config category is hidden opened its settings on
that page anyway, which the sidebar doesn't list, with nothing selected.
Open the first page the sidebar lists instead, skipping hidden ones.

BUG: 454579
---
 .../contents/configuration/AppletConfiguration.qml        | 8 +++++---
 1 file changed, 5 insertions(+), 3 deletions(-)

diff --git a/desktoppackage/contents/configuration/AppletConfiguration.qml b/desktoppackage/contents/configuration/AppletConfiguration.qml
index e452c7917e..21b3a368bd 100644
--- a/desktoppackage/contents/configuration/AppletConfiguration.qml
+++ b/desktoppackage/contents/configuration/AppletConfiguration.qml
@@ -223,11 +223,13 @@ Rectangle {
         }

         // if we are a containment then the first item will be ConfigurationContainmentAppearance
-        // if the applet does not have own configs then the first item will be Shortcuts
-        if (isContainment || !configDialog.configModel || configDialog.configModel.count === 0) {
+        // if the applet does not have own visible configs then the first item will be Shortcuts
+        if (isContainment || configDialogFilterModel.count === 0) {
             open(root.globalConfigModel.get(0))
         } else {
-            open(configDialog.configModel.get(0))
+            // the first page listed in the sidebar, skipping hidden ones
+            const firstVisible = configDialogFilterModel.mapToSource(configDialogFilterModel.index(0, 0));
+            open(configDialog.configModel.get(firstVisible.row))
         }
     }

-- 
2.53.0

From 72c0131a6d2ddd2be56acb30602f80dd3508cfc6 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 16:48:57 +0100
Subject: [PATCH] plasmoidviewer: Don't open settings on a hidden page

The config dialog always opened the applet's first category even when
hidden, so the desktop containment showed its Location page, which the
sidebar doesn't list. Open the first page the sidebar lists instead.

BUG: 454579
---
 .../shell/contents/configuration/AppletConfiguration.qml  | 8 +++++---
 1 file changed, 5 insertions(+), 3 deletions(-)

diff --git a/plasmoidviewer/qmlpackages/shell/contents/configuration/AppletConfiguration.qml b/plasmoidviewer/qmlpackages/shell/contents/configuration/AppletConfiguration.qml
index bcd089bd..ec9824c1 100644
--- a/plasmoidviewer/qmlpackages/shell/contents/configuration/AppletConfiguration.qml
+++ b/plasmoidviewer/qmlpackages/shell/contents/configuration/AppletConfiguration.qml
@@ -171,11 +171,13 @@ Rectangle {

     Component.onCompleted: {
         // if we are a containment then the first item will be ConfigurationContainmentAppearance
-        // if the applet does not have own configs then the first item will be Shortcuts
-        if (isContainment || !configDialog.configModel || configDialog.configModel.count === 0) {
+        // if the applet does not have own visible configs then the first item will be Shortcuts
+        if (isContainment || configDialogFilterModel.count === 0) {
             open(root.globalConfigModel.get(0))
         } else {
-            open(configDialog.configModel.get(0))
+            // the first page listed in the sidebar, skipping hidden ones
+            const firstVisible = configDialogFilterModel.mapToSource(configDialogFilterModel.index(0, 0));
+            open(configDialog.configModel.get(firstVisible.row))
         }
     }

-- 
2.53.0
